<template>
  <div class="mobile-page">
    <div class="mobile-header"><button class="back-button" @click="$router.back()">‹</button><b>青贮饲料管理</b><span></span></div>
    <section class="hero"><div><b>青贮饲料管理一张图</b><span>全省种植与收储态势总览</span></div><el-tag type="success" size="small">实时</el-tag></section>
    <div class="metrics"><div><b>{{ stats.subjects }}</b><span>种植主体</span></div><div><b>{{ stats.plots }}</b><span>种植地块</span></div><div><b>{{ stats.area }}</b><span>计划面积（亩）</span></div><div><b>{{ stats.yield }}</b><span>预计产量（吨）</span></div></div>
    <section class="card"><div class="card-title">青贮种植计划</div><div v-for="item in plans" :key="item.id" class="plan-row"><div><b>{{ item.subjectName }}</b><span>{{ item.regionName }} · {{ item.cropName || item.crop }}</span></div><strong>{{ item.area || item.supplementArea }} 亩</strong></div><el-empty v-if="!plans.length" description="暂无种植计划" :image-size="50" /></section>
    <section class="card"><div class="card-title">主体信息核查</div><p class="hint">现场走访时可快速查询种植户档案、年度计划和执行情况。</p><el-input v-model="keyword" placeholder="搜索主体名称或负责人" clearable /><div v-for="item in filteredGrowers" :key="item.id" class="grower-row"><div><b>{{ item.name }}</b><span>{{ item.owner }} · {{ item.regionName || item.regionCode }}</span></div><el-button link type="primary" @click="openGrower(item)">查看档案</el-button></div><el-empty v-if="!growers.length" description="未找到主体" :image-size="50" /></section>
    <el-drawer v-model="drawer" title="种植主体档案" size="88%"><template v-if="current"><el-descriptions :column="1" border size="small"><el-descriptions-item label="主体名称">{{ current.name }}</el-descriptions-item><el-descriptions-item label="负责人">{{ current.owner }}</el-descriptions-item><el-descriptions-item label="联系电话">{{ current.phone }}</el-descriptions-item><el-descriptions-item label="所属区域">{{ current.regionName || current.regionCode }}</el-descriptions-item><el-descriptions-item label="计划面积">{{ current.silageArea || 0 }} 亩</el-descriptions-item><el-descriptions-item label="预计产量">{{ current.expectedYield || 0 }} 吨</el-descriptions-item><el-descriptions-item label="计划执行情况">{{ current.latestStatus || '未申报' }}</el-descriptions-item></el-descriptions></template></el-drawer>
  </div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { fetchSilGrowers, fetchDeclarations } from '@/api/sil'
import { useUserStore } from '@/stores/user'
const userStore = useUserStore(); const growers = ref([]); const plans = ref([]); const keyword = ref(''); const drawer = ref(false); const current = ref(null); const stats = reactive({ subjects: 0, plots: 0, area: 0, yield: 0 }); const filteredGrowers = computed(() => growers.value.filter(item => !keyword.value || `${item.name}${item.owner}${item.phone}`.includes(keyword.value))); const openGrower = item => { current.value = item; drawer.value = true }; onMounted(async () => { growers.value = await fetchSilGrowers(userStore.role, {}); plans.value = (await fetchDeclarations(userStore.role)).filter(item => item.status !== 'rejected'); stats.subjects = growers.value.length; stats.plots = growers.value.reduce((sum, item) => sum + Number(item.plotCount || item.declarationCount || 0), 0); stats.area = plans.value.reduce((sum, item) => sum + Number(item.area || item.supplementArea || 0), 0); stats.yield = plans.value.reduce((sum, item) => sum + Number(item.expectedYield || 0), 0) })
</script>
