.mobile-page{background:#f5f6f8;padding:0 12px 24px}.mobile-header{height:58px;display:grid;grid-template-columns:42px 1fr 42px;align-items:center;text-align:center;font-size:20px}.back-button{border:0;background:none;font-size:38px;text-align:left}.hero,.card{background:#fff;border-radius:14px;padding:16px;margin-bottom:12px}.hero{display:flex;justify-content:space-between;align-items:center;background:linear-gradient(135deg,#3baa67,#73c83f);color:#fff}.hero b,.hero span{display:block}.hero span{font-size:12px;margin-top:5px;opacity:.88}.metrics{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-bottom:12px}.metrics div{background:#fff;border-radius:12px;padding:13px 10px}.metrics b,.metrics span{display:block}.metrics b{font-size:21px;color:#258651}.metrics span{font-size:12px;color:#98a2b3;margin-top:5px}.card-title{font-weight:700;color:#243b5a;margin-bottom:12px}.hint{font-size:12px;color:#98a2b3;line-height:1.6}.plan-row,.grower-row{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #edf0f5;padding:11px 0}.plan-row b,.plan-row span,.grower-row b,.grower-row span{display:block}.plan-row span,.grower-row span{font-size:12px;color:#98a2b3;margin-top:4px}.plan-row strong{color:#258651}.card :deep(.el-input){margin-bottom:8px}
</style>